+            if (obj == null)
+                return false;
+            if (getClass() != obj.getClass())
+                return false;
+            Sequence other = (Sequence) obj;
+            if (literalLen != other.literalLen)
+                return false;
+            if (matchDec != other.matchDec)
+                return false;
+            if (matchLen != other.matchLen)
+                return false;
+            return true;
+        }
