+        private void startSnapshotDeleter() {
+            enqueueAction(() -> {
+
+                boolean startedDeletion = false;
+                try (TransferableReleasables localReleasables = new TransferableReleasables()) {
+
+                    if (localReleasables.add(blockFullClusterRestart()) == null) {
