+
+            @Override
+            public int nextDoc() {
+                throw new UnsupportedOperationException();
+            }
+
+            @Override
+            public int advance(int target) {
+                if (target >= size()) {
+                    return NO_MORE_DOCS;
+                }
+                return index = target;
+            }
